// Builds web/dist/mii-x-ray.html: one self-contained page (styles, scripts and the C# runtime text inline) to upload
// to the MII server. No dependencies: each module keeps its own scope inside a small loader.
//   node web/build.mjs
import { readFileSync, writeFileSync, mkdirSync, readdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const web = dirname(fileURLToPath(import.meta.url));
const source = join(web, 'src');

// the C# runtime appended to every generated file; RuntimeSource.txt of the C# tool is the one source of it
const runtime = readFileSync(join(web, '..', 'src', 'Generate', 'RuntimeSource.txt'), 'utf8').replace(/^﻿/, '');
writeFileSync(join(source, 'runtime.js'),
  '// Generated by web/build.mjs from src/Generate/RuntimeSource.txt - do not edit.\nexport const RUNTIME_SOURCE = ' + JSON.stringify(runtime) + ';\n');

const modules = readdirSync(source).filter((name) => name.endsWith('.js')).sort();
const defined = modules.map((name) => {
  const exported = [];
  let code = readFileSync(join(source, name), 'utf8');
  code = code.replace(/^import \{([^}]+)\} from '\.\/([\w.]+)';$/gm, (line, names, module) => 'const {' + names + "} = __require('" + module + "');");
  code = code.replace(/^export (async function|function|class|const|let) (\w+)/gm, (line, kind, exportedName) => {
    exported.push(exportedName);
    return kind + ' ' + exportedName;
  });

  if (/^\s*(import|export)\b/m.test(code)) {
    throw new Error(name + ': an import or export form the bundler does not know');
  }

  return "__define('" + name + "', () => {\n" + code + '\nreturn { ' + exported.join(', ') + ' };\n});';
});

const loader = [
  '(() => {',
  "'use strict';",
  'const __factories = {};',
  'const __exports = {};',
  'const __define = (name, factory) => { __factories[name] = factory; };',
  'const __require = (name) => (__exports[name] ??= __factories[name]());',
  ...defined,
  "__require('app.js');",
  '})();',
].join('\n').replace(/<\/script/gi, '<\\/script');

const page = readFileSync(join(source, 'index.html'), 'utf8')
  .replace('<!--STYLE-->', () => '<style>\n' + readFileSync(join(source, 'app.css'), 'utf8') + '</style>')
  .replace('<!--SCRIPT-->', () => '<script>\n' + loader + '\n</script>');

mkdirSync(join(web, 'dist'), { recursive: true });
writeFileSync(join(web, 'dist', 'mii-x-ray.html'), page);
console.log('Built web/dist/mii-x-ray.html (' + Math.round(page.length / 1024) + ' KB)');
